import http from 'node:http';

const HOST = '127.0.0.1';
const PORT = 18099;
const MAX = 5 * 1024 * 1024;
let failures = 0;

function check(name, cond, extra = '') {
  if (cond) console.log(`PASS ${name}`);
  else { failures++; console.log(`FAIL ${name} ${extra}`); }
}

function request({ method, path, body, chunked = false, headers = {} }) {
  return new Promise((resolve, reject) => {
    const h = { 'content-type': 'application/json', ...headers };
    const buf = Buffer.isBuffer(body) ? body : Buffer.from(body ?? '', 'utf8');
    if (!chunked) h['content-length'] = buf.length;
    else h['transfer-encoding'] = 'chunked';
    const req = http.request({ host: HOST, port: PORT, method, path, headers: h }, (res) => {
      const chunks = [];
      res.on('data', (c) => chunks.push(c));
      res.on('end', () => {
        const raw = Buffer.concat(chunks);
        resolve({ status: res.statusCode, headers: res.headers, raw, text: raw.toString('utf8') });
      });
      res.on('error', reject);
    });
    req.on('error', reject);
    if (chunked) {
      // send in several chunks, including data after the limit is crossed
      const slice = 700 * 1024;
      for (let off = 0; off < buf.length; off += slice) req.write(buf.subarray(off, off + slice));
      req.end();
    } else {
      req.end(buf);
    }
  });
}

// Build a JSON body whose total UTF-8 length is exactly `total` bytes.
function exactSizePayload(total) {
  const pre = Buffer.byteLength('{"title":"边界","summary":"摘要","body":"');
  const post = Buffer.byteLength('"}');
  const fill = total - pre - post;
  return '{"title":"边界","summary":"摘要","body":"' + 'a'.repeat(fill) + '"}';
}

const run = async () => {
  // 1. small valid create
  let r = await request({ method: 'POST', path: '/api/articles', body: JSON.stringify({ title: '第一篇', summary: 's', body: '正文\n\n第二段' }) });
  check('small create 201', r.status === 201, `got ${r.status}`);
  const created = JSON.parse(r.text).article;
  check('created version 1', created.version === 1);

  // 2. exactly at the limit -> still saved
  const exactBody = exactSizePayload(MAX);
  check('exact payload size', Buffer.byteLength(exactBody, 'utf8') === MAX, String(Buffer.byteLength(exactBody, 'utf8')));
  r = await request({ method: 'POST', path: '/api/articles', body: exactBody });
  check('exact-limit create 201', r.status === 201, `got ${r.status}: ${r.text.slice(0, 120)}`);
  const big = r.status === 201 ? JSON.parse(r.text).article : null;

  // 3. one byte over -> 400 with complete JSON error (content-length framing)
  const overBody = exactSizePayload(MAX + 1);
  r = await request({ method: 'POST', path: '/api/articles', body: overBody });
  check('over-limit create 400', r.status === 400, `got ${r.status}`);
  let parsed = null;
  try { parsed = JSON.parse(r.text); } catch { /* incomplete body */ }
  check('over-limit create JSON error', parsed && typeof parsed.error === 'string' && parsed.error.length > 0, r.text.slice(0, 120));
  check('over-limit create error mentions size', parsed && /exceeds|too large|超过|大小|上限/.test(parsed.error), parsed && parsed.error);
  check('over-limit create content-length honored', Number(r.headers['content-length']) === r.raw.length, `${r.headers['content-length']} vs ${r.raw.length}`);

  // 4. chunked transfer, over limit, remaining chunks keep flowing -> same complete 400
  r = await request({ method: 'POST', path: '/api/articles', body: overBody, chunked: true });
  check('chunked over-limit 400', r.status === 400, `got ${r.status}`);
  parsed = null;
  try { parsed = JSON.parse(r.text); } catch { }
  check('chunked over-limit complete JSON', parsed && typeof parsed.error === 'string' && parsed.error.length > 0, r.text.slice(0, 120));
  check('chunked response fully received', Number(r.headers['content-length']) === r.raw.length, `${r.headers['content-length']} vs ${r.raw.length}`);

  // 5. multibyte content counts UTF-8 bytes, not characters
  // body of 中文 such that total bytes just exceed the limit
  const zhPre = Buffer.byteLength('{"title":"t","body":"');
  const zhPost = Buffer.byteLength('"}');
  const zhChars = Math.ceil((MAX + 1 - zhPre - zhPost) / 3); // 中 = 3 bytes
  const zhBody = '{"title":"t","body":"' + '中'.repeat(zhChars) + '"}';
  check('multibyte payload actually over', Buffer.byteLength(zhBody, 'utf8') > MAX);
  r = await request({ method: 'POST', path: '/api/articles', body: zhBody });
  check('multibyte over-limit 400', r.status === 400, `got ${r.status}`);

  // 6. no draft was added by the rejected creates
  r = await request({ method: 'GET', path: '/api/articles', body: '' });
  const list = JSON.parse(r.text).articles;
  check('rejected creates added nothing', list.length === 2, `list has ${list.length}`);

  // 7. PUT over limit -> 400, original article untouched
  const putOver = JSON.stringify({ title: big.title, summary: big.summary, body: 'x'.repeat(MAX), version: big.version });
  check('put payload over limit', Buffer.byteLength(putOver, 'utf8') > MAX);
  r = await request({ method: 'PUT', path: `/api/articles/${big.id}`, body: putOver });
  check('over-limit PUT 400', r.status === 400, `got ${r.status}`);
  parsed = null;
  try { parsed = JSON.parse(r.text); } catch { }
  check('over-limit PUT JSON error', parsed && typeof parsed.error === 'string' && parsed.error.length > 0);
  r = await request({ method: 'GET', path: `/api/articles/${big.id}`, body: '' });
  const after = JSON.parse(r.text).article;
  check('article unchanged after rejected PUT',
    after.title === big.title && after.summary === big.summary && after.body === big.body
    && after.id === big.id && after.createdAt === big.createdAt && after.version === big.version);

  // 8. chunked over-limit PUT also 400
  r = await request({ method: 'PUT', path: `/api/articles/${big.id}`, body: putOver, chunked: true });
  check('chunked over-limit PUT 400', r.status === 400, `got ${r.status}`);

  // 9. valid PUT at exactly the limit still works, version bumps
  const exactPut = (() => {
    const pre = Buffer.byteLength(`{"title":"t","summary":"","body":"`);
    const post = Buffer.byteLength(`","version":${big.version}}`);
    return `{"title":"t","summary":"","body":"${'b'.repeat(MAX - pre - post)}","version":${big.version}}`;
  })();
  check('exact PUT payload size', Buffer.byteLength(exactPut, 'utf8') === MAX, String(Buffer.byteLength(exactPut, 'utf8')));
  r = await request({ method: 'PUT', path: `/api/articles/${big.id}`, body: exactPut });
  check('exact-limit PUT 200', r.status === 200, `got ${r.status}: ${r.text.slice(0, 120)}`);
  if (r.status === 200) {
    const updated = JSON.parse(r.text).article;
    check('PUT version bumped', updated.version === big.version + 1);
    check('PUT id/createdAt kept', updated.id === big.id && updated.createdAt === big.createdAt);
  }

  // 10. normal small requests still fine after all this
  r = await request({ method: 'POST', path: '/api/articles', body: JSON.stringify({ title: '后续', body: '' }) });
  check('subsequent create 201', r.status === 201, `got ${r.status}`);

  console.log(failures === 0 ? '\nALL TESTS PASSED' : `\n${failures} TEST(S) FAILED`);
  process.exit(failures === 0 ? 0 : 1);
};

run().catch((e) => { console.error('test error:', e); process.exit(1); });

