import("node:http").then(({request}) => {
  const MAX = 5 * 1024 * 1024;
  const payload = Buffer.alloc(MAX + 2 * 1024 * 1024, "x");
  payload[0] = 0x7b; // not valid JSON, irrelevant: size check fires first
  const req = request({ host: "127.0.0.1", port: 18099, method: "POST", path: "/api/articles",
    headers: { "content-type": "application/json", "transfer-encoding": "chunked" } }, (res) => {
    const chunks = [];
    res.on("data", (c) => chunks.push(c));
    res.on("end", () => {
      const raw = Buffer.concat(chunks);
      let ok = false;
      try { const j = JSON.parse(raw.toString()); ok = typeof j.error === "string" && j.error.length > 0; } catch {}
      console.log("status:", res.status, "| complete JSON error:", ok, "| bytes:", raw.length, "| content-length:", res.headers["content-length"]);
      process.exit(res.status === 400 && ok ? 0 : 1);
    });
  });
  req.on("error", (e) => { console.error("request error:", e.message); process.exit(1); });
  // send 256KB chunks with 30ms delays — server crosses the limit long before the last chunk
  let off = 0;
  const tick = () => {
    if (off >= payload.length) { req.end(); return; }
    req.write(payload.subarray(off, off += 256 * 1024));
    setTimeout(tick, 30);
  };
  tick();
});'

